import React, { FunctionComponent, useMemo } from 'react';
import dayjs from 'dayjs';
import { Field } from 'react-final-form';
import classNames from 'classnames';
import { defineMessages } from 'react-intl';
import { useTranslation } from '@getvim/translate';
import InputValidationMessage from '../../inputValidationMessage';
import LabeledInput from '../../labeledInput';
import es from './translations/es.json';

import './index.less';

const messages = defineMessages({
  invalid: {
    defaultMessage: ' is invalid',
    id: 'schemaValidator.invalid',
  },
});

export type DateInputProps = {
  id?: string;
  label: string;
  hideLabel?: boolean;
  name: string;
  className?: string;
  dateFormat?: string;
  beforeToday?: boolean;
  todayValid?: boolean;
  placeholder?: boolean;
  onClick?: React.MouseEventHandler<HTMLInputElement>;
  placeholderFormat?: string;
};

function getDelimiterFromDateFormat(dateFormat: string): string {
  const defaultDelimiterAccordingToDefaultFormat = '/';

  if (dateFormat.includes('.')) {
    return '.';
  }
  if (dateFormat.includes('-')) {
    return '-';
  }

  return defaultDelimiterAccordingToDefaultFormat;
}

function allowOnlyNumbers(partsOfDate: string[]): string[] {
  return partsOfDate.map((partOfDate) => partOfDate.replace(/\D/g, ''));
}

const DateInput: FunctionComponent<DateInputProps> = ({
  id,
  label,
  hideLabel,
  name,
  className,
  dateFormat = 'MM/DD/YYYY',
  beforeToday = true,
  todayValid = false,
  placeholder,
  onClick,
  placeholderFormat,
}) => {
  const intl = useTranslation({ es } as any);
  const delimiter = useMemo(() => getDelimiterFromDateFormat(dateFormat), []); // eslint-disable-line react-hooks/exhaustive-deps
  const lengthOfEachDatePart = dateFormat.split(delimiter).map((partOfDate) => partOfDate.length);

  function isDateInputValid(date: string): string | undefined {
    const dateObject = dayjs(date, dateFormat);
    const now = dayjs();
    const isTodayValid = todayValid && dateObject.isSame(now, 'd');
    const isDateValid =
      date === undefined ||
      (dateObject.format(dateFormat) === date &&
        now.diff(dateObject, 'y') <= 120 &&
        (isTodayValid || (beforeToday ? dateObject.isBefore(now) : dateObject.isAfter(now))));
    return !isDateValid ? intl.formatMessage(messages.invalid) : undefined;
  }

  function onTextChange(
    newValue: string,
    previousValue: string,
    onChange: (event: any) => void,
  ): void {
    const value = newValue;
    const lastCharIndex = value.length - 1;
    const newChar = value[lastCharIndex]?.replace(/\D/g, '');
    let formattedDate = value;

    if (newValue.length > previousValue.length) {
      const numOfAllowedChars = dateFormat.length;

      const dateParts = value.substr(0, lastCharIndex).split(delimiter);
      const sanitizedDateParts = allowOnlyNumbers(dateParts);

      const dateWithDelimiters = sanitizedDateParts.map((partOfDate, index) =>
        partOfDate.length === lengthOfEachDatePart[index] && index < 2
          ? partOfDate + delimiter
          : partOfDate,
      );

      formattedDate = `${dateWithDelimiters.join('')}${newChar}`;

      if (formattedDate.length > numOfAllowedChars) {
        formattedDate = formattedDate.substr(0, numOfAllowedChars);
      }
    }

    onChange(formattedDate);
  }

  return (
    <Field
      name={name}
      validate={isDateInputValid}
      render={({ input, meta }) => (
        <div className="date-input">
          <LabeledInput
            {...input}
            id={id}
            className={classNames(className, meta.error && meta.touched && 'has-error')}
            type="text"
            active={meta.active || !!input.value}
            placeholder={
              placeholder ? dateFormat : meta.active ? placeholderFormat ?? dateFormat : undefined
            }
            htmlFor={id}
            label={hideLabel ? undefined : label}
            onChange={(event) => onTextChange(event.target.value, input.value, input.onChange)}
            onClick={onClick}
            value={input.value}
          />
          {meta.touched && meta.error && (
            <InputValidationMessage>{label + meta.error}</InputValidationMessage>
          )}
        </div>
      )}
    />
  );
};

export default DateInput;
